import { createCanonicalVeryfrontApiTransport, } from "../veryfront-api-transport.js";
/** Backward-compat alias; prefer holding a transport instance directly. */
export function requestWithRetry(url, apiToken, retryConfig, options = {}, outboundPolicy) {
    const { origin } = new URL(url);
    return createCanonicalVeryfrontApiTransport(origin, () => apiToken, retryConfig, outboundPolicy)
        .request(url, options);
}
